import{_ as o,C as t,o as a,c,a2 as r,b as d,w as l,a as s,E as n,a3 as m}from"./chunks/framework.DZUUNQ77.js";const P=JSON.parse('{"title":"FastXmlSerializer · 快速 XML 序列化","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/utils/fast-xml-serializer.md","filePath":"reference/helper/utils/fast-xml-serializer.md","lastUpdated":1784053534000}'),u={name:"reference/helper/utils/fast-xml-serializer.md"};function p(h,e,A,E,S,B){const i=t("Mermaid");return a(),c("div",null,[e[1]||(e[1]=r('<h1 id="fastxmlserializer-·-快速-xml-序列化" tabindex="-1">FastXmlSerializer · 快速 XML 序列化 <a class="header-anchor" href="#fastxmlserializer-·-快速-xml-序列化" aria-label="Permalink to &quot;FastXmlSerializer · 快速 XML 序列化&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/utils/FastXmlSerializer.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/utils/FastXmlSerializer.java</code></a></p></div><p><code>FastXmlSerializer</code> 实现 <code>XmlSerializer</code> 接口，对应 AOSP 同名类。它是一个不依赖 <code>XmlPullParserFactory</code>、直接往 <code>OutputStream</code>/<code>Writer</code> 写的轻量 XML 序列化器，比标准实现快，适合频繁持久化小配置。</p><h2 id="为什么不用标准-xmlserializer" tabindex="-1">为什么不用标准 XmlSerializer <a class="header-anchor" href="#为什么不用标准-xmlserializer" aria-label="Permalink to &quot;为什么不用标准 XmlSerializer&quot;">​</a></h2><p>VirtualXposed 的 server 进程在每次包列表/设备信息变更后都要落盘序列化。标准 <code>XmlPullParserFactory</code> 走 SPI 查找、有反射开销；<code>FastXmlSerializer</code> 是纯写、零依赖、直接拼字符串刷盘，延迟更低。</p><h2 id="主要方法" tabindex="-1">主要方法 <a class="header-anchor" href="#主要方法" aria-label="Permalink to &quot;主要方法&quot;">​</a></h2><p>实现 <code>XmlSerializer</code> 全套：<code>startDocument</code>/<code>endDocument</code>、<code>startTag</code>/<code>endTag</code>、<code>attribute</code>、<code>text</code>、<code>comment</code>、<code>cdsect</code>、<code>entityRef</code>、<code>processingInstruction</code>、<code>flush</code>、<code>setOutput</code> 等。</p><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p><code>PackagePersistenceLayer</code> / <code>DeviceInfoPersistenceLayer</code> 把 <code>PackageSetting</code> / <code>VDeviceInfo</code> 等结构序列化成 XML 落盘时，用 <code>FastXmlSerializer</code> 配合 <a href="./xml-serializer-and-parser"><code>XmlSerializerAndParser</code></a> 接口写入，读取时再用 <code>XmlPullParser</code> 解析。</p><h2 id="持久化读写流" tabindex="-1">持久化读写流 <a class="header-anchor" href="#持久化读写流" aria-label="Permalink to &quot;持久化读写流&quot;">​</a></h2>',10)),(a(),d(m,null,{default:l(()=>[n(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20W%5B%22%E5%86%99%E5%85%A5(server%20%E5%8F%98%E6%9B%B4%E5%90%8E)%22%5D%0A%20%20%20%20OBJ%5B%22PackageSetting%20%2F%20VDeviceInfo%22%5D%20--%3E%20XSAP%5B%22XmlSerializerAndParser.write%22%5D%0A%20%20%20%20XSAP%20--%3E%20FXS%5B%22FastXmlSerializer%3Cbr%2F%3E%E7%9B%B4%E6%8E%A5%E6%8B%BC%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%0A%20%20%20%20FXS%20--%3E%20AF%5B%22AtomicFile%3Cbr%2F%3E%E5%86%99%E4%B8%B4%E6%97%B6%E6%96%87%E4%BB%B6%2Brename%22%5D%0A%20%20%20%20AF%20--%3E%20DISK%5B%22XML%20%E6%96%87%E4%BB%B6%22%5D%0A%20%20end%0A%20%20subgraph%20R%5B%22%E8%AF%BB%E5%8F%96(%E5%90%AF%E5%8A%A8%E6%97%B6)%22%5D%0A%20%20%20%20DISK%20--%3E%20PULL%5B%22XmlPullParser%22%5D%0A%20%20%20%20PULL%20--%3E%20XSAP2%5B%22XmlSerializerAndParser.read%22%5D%0A%20%20%20%20XSAP2%20--%3E%20OBJ2%5B%22%E8%BF%98%E5%8E%9F%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20end%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>持久化层见 <a href="./../helper-top">helper 顶层</a>。</li><li>写入目标文件经 <a href="./atomic-file"><code>AtomicFile</code></a> 保证原子性。</li><li>序列化协议定义见 <a href="./xml-serializer-and-parser"><code>XmlSerializerAndParser</code></a>。</li></ul>',2))])}const X=o(u,[["render",p]]);export{P as __pageData,X as default};
